/* Seasons of Mystery – „Der Teufel im Moor“ (Buch S. 46–67), deutscher Text. Aufbau wie som-feuer.js. */
window.VAE_MYS = window.VAE_MYS || {};
VAE_MYS.teufel = {
 titel: "Der Teufel im Moor", buch: "vae_seasons", p: 46, zeit: "Herbst", ort: "Jütland · Grimsted Lyng",
 warnung: "Gewalt, Tod von Kindern", bild: "som/teufel_eroeffnung",
 tabs: [["Hintergrund","hg"],["Anreise","an"],["Orte","orte"],["Konfrontation","kf"],["|"],["Figuren","fg"],["Hinweise","hw"],["Handouts","ho"],["Nachspiel","ns","end"]],
 pp: {hinter: 47, konf: 65, myth: 54, einl: 49, vorb: 50, reise: 50, ankunft: 51, karte: 56, cd: 54},

 hg: {
  intro: "Die Spielercharaktere reisen in ein gottverlassenes Moor an der Westküste Jütlands, wo ehrgeizige Ingenieure im Streben, die Landschaft zu zähmen und zu modernisieren, dunkle Mächte geweckt haben.",
  vorspiel: "Dieser erste Abschnitt beschreibt den Hintergrund des Mysteriums und die Konflikte, auf denen es beruht, einschließlich des Vaesens des Szenarios – eines Mylings, das sich der Namenlose nennt. Eine Einladung eröffnet die Sitzung, danach folgt die Reise nach Grimsted Lyng auf der dänischen Halbinsel Jütland. Dieser Abschnitt enthält auch einen Countdown von Ereignissen, mit dem du als Spielleiter Schwung in die Geschichte bringst. Der zweite Teil des Textes stellt die verschiedenen Orte vor, die die Spielercharaktere besuchen können. Das Mysterium endet mit einer Konfrontation und einer Übersicht der wichtigen Nichtspielercharaktere.",
  hinter: [
   "Grimsted Lyng ist eine windumtoste Heidelandschaft, die sich westlich der alten Heerstraße zwischen der Handelsstadt Viborg in Jütland, Dänemark, und der Freien Stadt Hamburg in Norddeutschland bis ans Meer erstreckt. Einst war dies ein fruchtbares Land, bewohnt von stolzen und wohlhabenden Bauern, doch Brandrodung und Überweidung forderten einen hohen Tribut vom Boden. Die Gier der Menschen, dazu Pestepidemien und plündernde Soldaten, ließen das Ackerland langsam verkommen. Windverwehter Sand vermischte sich mit der ausgelaugten Erde, und die Felder wurden von Heidekraut überwuchert. Die Menschen, die dennoch blieben, konnten den ökologischen Wandel nicht aufhalten und passten sich dem Leben auf dem kargen Moor an. Sie wurden Moorbauern und lebten von der Schafzucht und vom Torfstechen, den sie in den Mooren der öden Heide gewannen.",
   "Hunderte von Jahren lang waren die Menschen des Moors weitgehend von der Außenwelt abgeschnitten. Die Moorbauern führten ein hartes und karges Leben, doch weder Krone noch Kirche belästigten sie mit Steuern oder Forderungen nach Anpassung. Zu Beginn des 19. Jahrhunderts begann sich das jedoch zu ändern. Große Zahlen von Landvermessern wurden aus Kopenhagen geschickt, um das Land von den Verwüstungen der napoleonischen Kriege wieder aufzubauen. Bald stießen Ingenieure mit rauchenden Maschinen und Träumen dazu, die Moore Jütlands in moderne landwirtschaftliche Flächen zu verwandeln. Dänemark würde wieder aufblühen – und der Weg in diese glückselige Zukunft führte über die industrielle Großlandwirtschaft.",
   "Zehn Jahre vor Beginn des Mysteriums wird die Dänische Gesellschaft zur Urbarmachung der Heide gegründet, umgangssprachlich die Moorgesellschaft genannt. Diese Gesellschaft ist erfüllt vom Geist der Innovation und des Fortschritts, der diese Epoche prägte. Mit Dampfkraft und anderen technischen Errungenschaften arbeiten die Ingenieure der Moorgesellschaft daran, den kargen Mooren mit künstlichem Dünger, Baumpflanzungen und Entwässerungskanälen wieder Fruchtbarkeit zu geben. Doch nun ist die Moorgesellschaft bei einem Entwässerungsprojekt auf Grimsted Lyng auf unerwartete Probleme gestoßen. Etwas dort draußen macht den Arbeitern Angst und hat mehrere von ihnen dazu gebracht, ohne Erklärung zu gehen – ohne auch nur ihren ausstehenden Lohn abzuholen. Außerdem stimmt etwas mit dem Entwässerungssystem nicht. Rohre bersten, Schläuche werden durchlöchert, und die große Dampfpumpe, die die Maschinerie antreibt, ist durch plötzliche Überhitzung beinahe explodiert.",
   "Der Chefingenieur der Moorgesellschaft, Preben Rasmussen, vermutet, dass einige Einheimische das Projekt aktiv sabotieren, womöglich durch schwarze Magie. Ihr Unternehmen ist bei den Menschen auf dem Moor auf Feindseligkeit gestoßen, und Rasmussen hat Geschichten über dämonische Wesen gehört, mit denen die Bauern auf verschiedene Weise zu tun haben. Vor allem hat er vom „Teufel im Moor“ gehört: einem geflügelten Phantom mit glühenden Augen, das nach dem Pfarrer und Volkskundler Gabriel Sandemann auf Grimsted Lyng als Schutzengel gilt. In einem handschriftlichen Tagebuch vom Anfang des 19. Jahrhunderts, das Rasmussen auf seinen Inspektionsreisen in der Gegend an sich genommen hat, beschreibt Sandemann, wie die Menschen des Moors seit Jahrhunderten bei diesem Vaesen in allerlei praktischen Dingen Hilfe suchen. Der örtlichen Überlieferung nach half der Teufel im Moor, plündernde Soldaten zu vertreiben und Pestratten von den Siedlungen der Moorbauern fernzuhalten. Diese Geschichten haben Rasmussen – einen praktisch veranlagten und aufgeschlossenen Ingenieur – zu folgender Hypothese geführt: Vielleicht liegt die Wurzel des Problems darin, dass jemand dieses Vaesen angeworben hat, um die Moorgesellschaft zu stoppen und den menschlichen Fortschritt aufzuhalten?",
   "Rasmussen hat ein Telegramm an Linnea Elfeklint geschickt, denn er hatte als junger Student von der Gesellschaft erfahren und mehrere Kontakte unter den sogenannten Rosenbergern an der Polytechnischen Universität Dänemarks geknüpft. Stark von Letzteren beeinflusst, sieht Rasmussen die Lage ziemlich vereinfacht. Am liebsten sähe er, dass die Gesellschaft tötet, was auch immer auf dem Moor spukt, und jede Spur lokalen Teufelskults und alles andere auslöscht, was die Tätigkeit der Moorgesellschaft behindert.",
   "Doch der ehrgeizige Chefingenieur hat die eigentliche Ursache des Problems völlig missverstanden. Es stimmt, dass ein Vaesen beteiligt ist, aber es war Rasmussen selbst, der es geweckt hat. Das ganze Mysterium dreht sich um Sandemanns Tagebuch voller Mythen und Volkskunde. Sandemann war nicht nur Pfarrer und Volkskundler, sondern auch ein Frauenheld, und auf seinen Reisen durch die Gegend knüpfte er ein Verhältnis mit einem Bauernmädchen namens Signe Andersdotter. Doch Sandemann ließ sie in ihrer Not im Stich, als das Kind in Signes Bauch es unmöglich machte, ihre skandalöse Beziehung geheim zu halten. Bald ging Signe, verstoßen und allein, hinaus aufs Moor und brachte heimlich das Kind zur Welt. In ihrer Verzweiflung ertränkte sie ihren Säugling in einem Tümpel, bevor sie ihren Weg über das Moor fortsetzte, wo die junge Mutter wenige Tage später erfroren aufgefunden wurde.",
   "Diese Tragödie, die für die Zeit typisch war, ereignete sich etwa fünfzig Jahre vor dem Mysterium und ist von den Moorbauern weitgehend vergessen worden. Die einzige Ausnahme ist Signes alte Mutter – Oma Thea –, die noch lebt, aber für sich bleibt, in einer kleinen Kate am Rand der Häusergruppe, die die Moorbauern Grimsted Hus nennen. Alles änderte sich, als Rasmussen im Auftrag der Moorgesellschaft auftauchte. Er brachte nicht nur moderne Technik und kräftige Arbeiter mit, sondern auch Sandemanns Tagebuch. Ohne die tragische Geschichte zu kennen, nahm er das Tagebuch mit zu dem Sumpfgebiet, in dem Signe einst ihr Kind gebar und ertränkte. Dabei erwachte das tote Kind als Myling, von einem einzigen Ziel besessen: seinen eigenen Tod und den seiner Mutter zu rächen, indem es Sandemann tötet. Dass Sandemann längst tot und begraben ist, macht keinen Unterschied – der Myling, der sich der Namenlose nennt, richtet seinen ganzen Hass auf das Tagebuch und auf die Person, die es bei sich trägt. Dieser Myling hat Rasmussens Saisonarbeiter verscheucht und mit seinem aufgestauten Hass die Dampfpumpe in mehreren kritischen Situationen überhitzen lassen."
  ],
  mythic: "Der Teufel im Moor lässt sich ohne Änderungen an der Geschichte leicht in einen britischen Zusammenhang übertragen. Den Konflikt zwischen den Einheimischen und der Moorgesellschaft kannst du durch Verweise auf die Ludditen vertiefen: empörte Arbeiter, die Anfang des 19. Jahrhunderts Dampfmaschinen und andere Neuerungen sabotierten, die ihrer Meinung nach ihre traditionellen Einkommensquellen bedrohten. Anstelle des erfundenen Grimsted Lyng könnte das Mysterium auf Dartmoor im Südosten Englands spielen. Dieses sagenhafte Moor ist ein beinahe archetypischer Horrorschauplatz voller Rätsel und lokaler Sagen über kopflose Reiter, heimgesuchte Grabstätten und heulende Höllenhunde. Inspiration bietet die klassische Sherlock-Holmes-Geschichte Der Hund von Baskerville (1901–1902) von Sir Arthur Conan Doyle, die auf Dartmoor spielt.",
  konflikt: [
   "Der Hauptkonflikt dieses Mysteriums ist der Drang des Namenlosen, sich an Gabriel Sandemann zu rächen, der die Mutter des Kindes so feige im Stich ließ und sie zu der verzweifelten Tat zwang, die auch ihr eigenes Verderben wurde. Doch von Sandemann ist nur das handgeschriebene Tagebuch übrig, das Rasmussen mitgebracht hat. Deshalb ist dieses Artefakt – oder vielmehr sein Besitzer – das Ziel des Hasses des Namenlosen. Der natürliche Endpunkt dieses Konflikts ist, dass der Myling die Person tötet, die das Tagebuch trägt, sei es Rasmussen oder eine Spielerfigur.",
   "Der Nebenkonflikt betrifft die gespannten Beziehungen zwischen der Moorgesellschaft und der einheimischen Bevölkerung. Viele in der Gegend sehen in der Moorgesellschaft eine Bedrohung für ihre Gemeinschaft und ihre Traditionen, weshalb zwei der gewalttätigeren Bauern in der Siedlung Grimsted Hus – mit Billigung der anderen – die Entwässerungsanlagen sabotiert haben. Die durchlöcherten Schläuche sind nicht das Werk des Mylings, und die Spielercharaktere können deutliche Spuren von Messern und anderem menschlichem Werkzeug finden."
  ]
 },

 an: {
  hoName: "Handout 3A", karten: ["teufel_karte_jylland", "teufel_karte_grimsted"],
  einladung: [
   "Dieses Mysterium spielt im Herbst und beginnt damit, dass die Spielercharaktere eine Nachricht von Linnea Elfeklint erhalten, die sie bittet, sie in der Irrenanstalt von Upsala zu besuchen (Handout 3A).",
   "Ein heulender Herbstwind weht durch die Stadt, und die Pflastersteine sind mit gelben Blättern bedeckt. Die Bettler drängen sich in schmalen Gassen zusammen, und überall in der Stadt eilen Studenten mit flatternden Schals und dicken Büchern unter dem Arm umher. Die Irrenanstalt wirkt noch düsterer und bedrohlicher als sonst. Die kahlen Bäume hinter den schwarzen Eisentoren lassen den Ort wie einen Totenhof erscheinen, ebenso die Schreie und das qualvolle Wimmern, die aus den vergitterten Fenstern dringen. Die Spielercharaktere werden von einem Pfleger empfangen, der aufleuchtet, als er merkt, dass sie zu Linnea wollen. „Wurde auch Zeit“, sagt er. „Sie ist in letzter Zeit ungewöhnlich verstört; murmelt wirr von dem Dunklen und einem seltsamen Mann namens Sandemann. Ist das jemand, den Sie kennen?“",
   "Er führt die Spielercharaktere in einen zellenartigen Raum, in dem Linnea auf einer einfachen Holzbank liegt, mit dicken Lederriemen festgeschnallt. Als sie eintreten, schreckt sie hoch und wirkt bemerkenswert fröhlich und ausgeruht. „Achtet nicht auf die Riemen“, sagt sie, während der Pfleger ihr auf die Beine hilft. „Ich hatte in letzter Zeit unruhige Träume.“ Nachdem sie den Pfleger weggeschickt – und eine Kanne Tee für sich und ihre Gäste bestellt – hat, zieht sie das Telegramm von Preben Rasmussen hervor (Handout 3B) und erklärt, dass die Spielercharaktere sich beeilen müssen, nach Grimsted Lyng auf der dänischen Halbinsel Jütland zu kommen. Dort stehe etwas Schreckliches bevor: „Ich fürchte das Schlimmste“, murmelt Linnea. „Die dänischen Moore sind seit Langem die Heimat mächtiger Vaesen – und königliche Ingenieure mit moderner Maschinerie haben oft wenig Respekt vor dem Unsichtbaren.“",
   "Bald kommt der Pfleger mit einer Kanne frisch gebrühten Tees zurück, dazu Kekse und eine passende Anzahl Porzellantassen. Fröhlich schlürfend erzählt Linnea, dass sich der Service erheblich verbessert habe, seit sie dem Oberarzt Frejd bei der Lösung eines kleinen Mysteriums geholfen hat: „Einer der Schornsteine wurde von einem mürrischen alten Karolinger heimgesucht, aber als ich dem elenden Ding erklärte, dass König Karl XII. seit mehr als anderthalb Jahrhunderten tot und begraben ist – und übrigens vollkommen durchlöchert von Silberknöpfen –, gab er auf und verließ schließlich seinen Posten.“ Sie erzählt, dass Preben Rasmussen ein angesehener Ingenieur aus Kopenhagen ist, der irgendeine Verbindung zur Moorgesellschaft hat. Sie korrespondieren seit Jahren über „Angelegenheiten von Wichtigkeit“, wie Linnea es nennt, haben sich aber nie getroffen. Linnea vermutet, dass Rasmussen ein Rosenberger sein könnte, da diese militantere Ausprägung des alten Ordens der Artemis viele Sympathisanten unter den Kindern des Donnerstags in der dänischen Hauptstadt hat. Sie erwähnt auch Gabriel Sandemann, einen Pfarrer und Volkskundesammler, der zu Beginn des Jahrhunderts Tausende von Sagen über Vaesen und Magie in der alten dänischen Bauerngesellschaft gesammelt hat. Er gilt als einer der großen Pioniere der nordischen Volkskunde, doch nach Linneas Worten war er in Wahrheit ein Rosenberger, der Informationen über „die Horden Satans“ sammelte, um sie aus Gottes Schöpfung zu verbannen.",
   "Linnea seufzt und wirkt plötzlich furchtbar müde. Sie wiederholt, dass die Spielercharaktere nach Grimsted Lyng müssen. Sie ist sicher, dass Preben Rasmussen mit seinen „modernen Schrecken“ ein mächtiges Vaesen auf dem Moor gestört hat. Sie fürchtet, dass Rasmussen – als Ingenieur und mutmaßlicher Rosenberger – etwas Dummes tun wird, das den Konflikt verschärft und das empfindliche Gleichgewicht zwischen Vaesen und Menschen weiter stört. „Wenn Sandemann recht hatte, ist es wirklich sehr ernst. Draußen auf den dänischen Mooren gibt es Vaesen, die seit Tausenden von Jahren als Götter und mörderische Wächter verehrt werden.“",
   "Dann wird sie still und legt sich auf die Bank. Sie sei zu müde, um weiterzumachen, sagt sie. Die Albträume seien zu grausam – die über das Moor und das, was dort draußen wartet. Nachdem sie angemerkt hat, dass sie persönlich den Zug nach Göteborg und dann einen Dampfer nach Frederikshavn in Jütland genommen hätte, wendet Linnea das Gesicht zur Wand und macht deutlich, dass sie allein sein will. Respektieren die Spielercharaktere ihren Wunsch nicht, erleidet sie bald einen Nervenzusammenbruch und beginnt hysterisch zu schreien. Ein halbes Dutzend Pfleger stürmt in den Raum und bringt Linnea in einen geschlossenen Abschnitt der Anstalt, wo sie für den Rest des Mysteriums bleibt."
  ],
  brief: {
   t1: "Liebe Freunde,",
   x: ["ich habe eine dringende Nachricht von unseren dänischen Gefährten erhalten und fürchte, dass dunkle Mächte am Werk sind. Wenn an den Hinweisen auf Sandemann etwas Wahres ist, ist die Lage äußerst ernst. Bitte besucht mich so bald wie möglich in der Anstalt und bereitet euch darauf vor, das Land zu verlassen."],
   sig: "Mit freundlichen Grüßen, Linnea"
  },
  vorb: ["Wie üblich können sich die Spielercharaktere in ihrem Hauptquartier auf die Reise vorbereiten und dadurch einen Vorteil erhalten (siehe Kapitel 9 im Grundregelwerk).",
         "Spielercharaktere, die in Upsala nach Informationen suchen, finden automatisch Folgendes:",
         "· Einen Zeitungsartikel über die Modernisierung der dänischen Moore durch die Moorgesellschaft (Handout 3C).",
         "· Eine Stelle in einem alten Wälzer mit dem Titel Unterirdische Vaesen und ihre Verehrer im Norden, in der Gabriel Sandemann und seine unermüdliche Suche nach Sagen, Magie und okkulten Traditionen in der dänischen Bauerngesellschaft erwähnt werden (Handout 3D)."],
  kaesten: [
   {t:"Preben Rasmussens Telegramm (Handout 3B)", p:51, x:"Vom Postamt Viborg an die Telegraphenstation Upsala<br><br>Verehrte Gnädige<br>Benötige dringend Hilfe STOPP Eindeutige dämonische Präsenz auf Grimsted Lyng STOPP Angriffe auf das Arbeitslager der Moorgesellschaft STOPP Unnatürliche Schäden an der Ausrüstung STOPP Die Männer vor Angst außer sich STOPP Zorn und Narrheit der Einheimischen STOPP Fürchte, es ist G Sandemanns Teufel STOPP Erwarte Ihre Ankunft im Gasthaus Grimsted STOPP"},
   {t:"Fortschritt kommt ins finsterste Jütland (Handout 3C)", p:51, x:"Mit den allerneuesten Mitteln von Technik und Wissenschaft haben fleißige Ingenieure aus der königlichen Hauptstadt Kopenhagen es auf sich genommen, die kargen Moore der jütländischen Halbinsel zu zivilisieren. Es ist die Dänische Gesellschaft zur Urbarmachung der Heide, die vielen unserer Leser bereits bekannt sein dürfte, die diese mannhafte Initiative startet. Die Moore sollen trockengelegt, die Heide ausgejätet und germanische Bäume mit männlichen Wurzeln gepflanzt werden, um den Boden zu festigen und die Ernten vor dem Flugsand zu schützen. Ferner sollen die neuesten Wunder des künstlichen Düngers eingesetzt werden, entwickelt von den fleißigen und genialen Forschungsingenieuren der Polytechnischen Universität Dänemarks. Einer dieser furchtlosen Fackelträger der Zivilisation ist der berühmte Dampfingenieur Preben Rasmussen, der die Expedition der Moorgesellschaft in das weite Moor von Grimsted Lyng leiten wird: ein primitiver und gottverlassener Teil Dänemarks, der nach Rasmussens Worten ebenso gut im finstersten Afrika liegen könnte. „Ich habe demütig die edle Aufgabe angenommen, Zivilisation und menschlichen Fortschritt zu sichern“, sagte Herr Rasmussen unserem Reporter. Er fügt hinzu, dass seine einzige Sorge sei, wie die einheimische Bevölkerung auf seine Dampfmaschine reagieren werde: „Man hört von den Ludditen-Irren in England.“"},
   {t:"Fragment aus „Unterirdische Vaesen und ihre Verehrer im Norden“ (Handout 3D)", p:52, x:"Obwohl Studien der chthonischen Kräfte stets schwierig durchzuführen und gefährlich für Leib und Leben sind, enthält die Geschichte der nordischen Wissenschaft zahlreiche Beispiele, die selbst internationalen Leuchten wie den furchtlosen Brüdern Wilhelm und Jacob Grimm in Deutschland und dem Großmeister-Alchemisten Isaac Newton Konkurrenz machen. Ein wichtiger Pionier in unserer eigenen Ecke der Welt ist der Däne Gabriel Sandemann, der in den Jahrzehnten zwischen Bonapartes Kriegen und dem Aufkommen der Eisenbahn unter Bauern und einfachen Leuten umherreiste, um ihre Beziehung zum Unterirdischen zu dokumentieren. Sandemann war ein imposanter Mann – groß und stark an Leib und Seele –, der auf seinen vielen Reisen durch die dänische Bauerngesellschaft in ihrer letzten Blüte Tausende von Sagen und Augenzeugenberichten über unterirdische Vaesen und ihr Verhältnis zur Menschheit sammelte. Am bemerkenswertesten ist vielleicht seine Dokumentation der wundersamen und doch furchterregenden Vaesen, die die berühmten dänischen Moore heimsuchen."}
  ],
  reise: ["Die Spielercharaktere brechen an einem kalten und regnerischen Oktobermorgen aus Upsala auf. Folgen sie Linnea Elfeklints Rat, dauert die Reise genau fünf Tage – zuerst mit dem Zug über die Westliche Hauptbahn nach Göteborg, dann mit dem Dampfer über das Skagerrak zum Fischerdorf Skagen an der Nordspitze Jütlands. Von dort geht es mit dem Zug weiter nach Viborg in der Mitte der Halbinsel, wo die Spielercharaktere die Postkutsche zum Gasthaus Grimsted am Ostrand von Grimsted Lyng nehmen. Wie üblich kann jede Spielerfigur während der Reise einen Vorteil erhalten (siehe Grundregelwerk S. 24)."],
  ankunft: ["Die Kutsche erreicht das Gasthaus Grimsted am späten Nachmittag. Abgesehen davon, dass sie nach der langen Reise müde sind, sind die Spielercharaktere wund davon, den größten Teil des Tages in einer vollgepackten Kutsche auf Straßen von zweifelhafter Qualität durchgeschüttelt worden zu sein. Es dämmert bereits, und eisige Böen wehen vom düsteren Moor herüber – weit, kahl und öde, auf der anderen Seite des Gasthauses. Das Gasthaus Grimsted ist die örtliche Schänke und wird unter Orte genauer beschrieben. Es besteht aus drei verbundenen Fachwerkhäusern im traditionellen schlichten dänischen Stil mit Strohdächern und einem geräumigen Hof. Mehrere große Kutschen und Wagen stehen draußen. Ein schön bemaltes Holzschild mit dem königlichen Monogramm und einem stilisierten Posthorn zeigt, dass das Gasthaus zugleich Poststation und Knotenpunkt des organisierten Kutschdienstes ist. Hier endet auch die Straße. Mehrere Pfade führen hinaus aufs Moor, aber von hier aus müssen die Spielercharaktere zu Fuß weiter.",
   "Als die Spielercharaktere aus der Kutsche steigen, tritt ein ernster junger Mann in grobem Anzug aus dem Gasthaus. Mit entschlossenem Schritt geht er auf sie zu. Nachdem er gefragt hat, ob sie die „Experten“ aus Upsala seien, stellt er sich als Jens Ludvigsen vor, erster Assistent des Chefingenieurs Rasmussen und wissenschaftlicher Sekretär der Moorgesellschaft. Er wirkt eilig und erklärt, dass er mehrere Tage auf sie gewartet hat, es also keine Zeit zu verlieren gibt. Ingenieur Rasmussen hat eine furchtbare Entdeckung gemacht, die zeigt, wie ernst die Lage geworden ist. Ludvigsen will nicht ins Detail gehen, da er glaubt, es übersteige sein Verständnis – und weil es ihm einen Heidenschrecken einjagt. Doch wenn die Spielercharaktere eine Probe auf MANIPULATION bestehen, flüstert der verängstigte Mann, es gehe um „eine Leiche, einen winzigen Säugling!“",
   "Da es zu spät ist, um noch aufs Moor zu gehen, hat Ludvigsen veranlasst, dass die ganze Gruppe die Nacht im Gasthaus Grimsted verbringt. Die Moorgesellschaft übernimmt die Kosten, einschließlich Mahlzeit und Getränk. Er schlägt jedoch vor, dass die Spielercharaktere von nun an in ihrem Arbeitslager schlafen. Dort wurde ein Zelt aufgestellt, und die Spielercharaktere werden auf Kosten der Gesellschaft verpflegt.",
   "Während die Spielercharaktere mit Ludvigsen sprechen, nimmt der Kutscher ihre Koffer vom Wagen. Eine Spielerfigur, die eine Probe auf WACHSAMKEIT besteht, bemerkt plötzlich in der Dämmerung einen großen schwarzen Vogel, der auf einem einsamen Baum sitzt. Es ist fast, als beobachte der Vogel sie, und einen Moment lang scheinen seine Augen in einem geisterhaften grünen Licht zu schimmern. Als die Spielerfigur das nächste Mal dorthin schaut, ist der Vogel verschwunden.",
   "Ludvigsen folgt den Spielercharakteren in die Gaststube und stellt sie Kromutter Pedersen vor, der imposanten Wirtin des Gasthauses. Er verabschiedet sich bald und zieht sich in die Schlafnischen im Obergeschoss zurück, da ihnen ein früher Morgen bevorsteht. Nun haben die Spielercharaktere Gelegenheit, sich unter die Einheimischen zu mischen und Fragen zu Menschen und Orten in der Gegend zu stellen. Am Morgen werden sie im Morgengrauen von Ludvigsen geweckt, der sie nach einem einfachen Frühstück, das Kromutter zubereitet hat, hinaus aufs windumtoste Moor begleitet. Im Herbstregen führt er sie auf gewundenen Pfaden zum Lager der Moorgesellschaft."]
 },

 cdIntro: "Dass die Spielercharaktere im Gasthaus Grimsted ankommen, bleibt dem Namenlosen nicht verborgen, der rachsüchtig alles beobachtet, was im und um das Lager der Moorgesellschaft geschieht. Alles, was mit Rasmussen und Sandemanns Tagebuch zu tun hat, ist von Interesse und womöglich einen Mord wert. Mit den folgenden Ereignissen kannst du bei Bedarf das Tempo des Spiels erhöhen und die Spieler zur abschließenden Konfrontation drängen:",
 cd: [
  {n:"Nebel und Licht", x:"Der Namenlose erzeugt mit Magie Chaos im Arbeitslager und verscheucht so viele Menschen wie möglich aus der Umgebung des Gegenstands seines Hasses – Gabriel Sandemanns Tagebuch. Zuerst setzt er die Verzauberung NEBEL ein und hüllt das Lager in dichte Schleier, die wie gefräßige Schlangen zwischen den Zelten kriechen. Danach setzt er MAREEL ein, um ein schimmerndes grünes Licht zu erzeugen, das an verschiedenen Stellen im Lager aufflackert. Spielerfiguren, die den Namenlosen in Vogelgestalt gesehen haben, erkennen das geisterhafte Leuchten aus den augenlosen Höhlen des Mylings wieder. Alle Spielerfiguren müssen eine Furchtprobe gegen Furcht 1 ablegen. Drei Arbeiter der Moorgesellschaft verschwinden mit einem Schrei im Nebel und werden nie wieder gesehen."},
  {n:"Die Saboteure", x:"Hans und Ejnar Jensen, zwei betrunkene Taugenichtse aus Grimsted Hus, werden von Preben Rasmussen auf frischer Tat ertappt, als sie die Dampfpumpe der Moorgesellschaft sabotieren wollen. Rasmussen ist außer sich und schleift die Saboteure samt seiner gesamten Mannschaft zurück nach Grimsted Hus. Er besteht darauf, dass auch die Spielercharaktere mitkommen. In der Siedlung angekommen, verkündet Rasmussen, dass er die Saboteure gefasst hat und die Behörden verständigen will. Er zieht Sandemanns Tagebuch hervor – haben die Spielercharaktere es (siehe unten), bittet er sie, es zurückzugeben – und hält es für alle sichtbar hoch: „Die Zeit ist gekommen, mit den alten Traditionen zu brechen – der Teufel hat im Zeitalter der Dampfkraft keinen Platz!“ Alle im Dorf kommen, um zu sehen, was los ist, auch die alte Oma Thea. Als sie das Tagebuch sieht, zeigt sie auf Rasmussen und ruft: „Merkt euch meine Worte, der einzige Teufel auf dem Moor war Sandemann selbst!“ Im nächsten Moment sehen alle einen riesigen schwarzen Vogel, der sich von einem Dach in die Luft schwingt und übers Moor davonfliegt. Der Namenlose hat die ganze Zeit zugesehen. Aufgewühlt von Oma Theas Reaktion wirkt er eine Verzauberung, die den Boden rund um Rasmussen in einen einen Meter tiefen Tümpel aus nassem Schlamm verwandelt, voller Knochen und wimmelnd von weißen Maden. Alle geraten in Panik und rennen schreiend aufs Moor. Drei Arbeiter der Moorgesellschaft werden nie wieder gesehen. Die Spielerfiguren müssen eine Furchtprobe gegen Furcht 1 ablegen."},
  {n:"Ludvigsens Tod", x:"Der Namenlose setzt erneut die Verzauberung NEBEL ein und hüllt das Lager in dichten Nebel. Diesmal will er die Menschen nicht nur erschrecken, sondern betritt das Lager mit mörderischer Absicht. Es zieht ihn zum Tagebuch, doch die erste Person, der er begegnet, ist Rasmussens Assistent Jens Ludvigsen. Der Myling erscheint ihm in seinem ganzen Grauen und tötet ihn mit dem Fluch TODESKÄLTE in Form eines gewaltigen Schwalls eiskalten Moorwassers. Die Spielercharaktere hören Ludvigsens Todesschreie, können aber nicht rechtzeitig dort sein, um ihn zu retten. Sie hören auch die Flügelschläge eines riesigen Vogels, als ein dunkler Schatten im Nebel davonfliegt. Ludvigsens Leiche wird mitten im Lager gefunden, steif und vom Kältezauber des Namenlosen verdreht, triefend von stinkendem Moorwasser. Die Spielerfiguren müssen eine Furchtprobe gegen Furcht 1 ablegen."},
  {n:"Katastrophe", kat:1, x:"Der Myling setzt die Verzauberung ÜBERHITZUNG ein, um die Dampfpumpe in die Luft zu sprengen, während Preben Rasmussen (oder die Spielerfigur, die Sandemanns Tagebuch trägt) im Lager der Moorgesellschaft ist. Die Explosion hat Sprengkraft 12 und verwüstet das gesamte Lager; sie tötet jeden Nichtspielercharakter im Gebiet."}
 ],

 orteIntro: "Grimsted Lyng ist eine öde und in vieler Hinsicht furchteinflößende Landschaft: weit, verlassen und von heulenden Winden aus dem westlichen Meer gepeitscht. Ein eisiger Herbstregen peitscht den Spielerfiguren ständig ins Gesicht, wenn sie sich zwischen den auf der Karte (S. 56) markierten Orten bewegen. Setze den Namenlosen in Vogelgestalt ruhig ein, um die Spielerfiguren bei ihren Wanderungen unter Druck zu setzen. Sie könnten ihn etwa als bedrohlichen Schatten auf dem Moor bemerken oder als allsehende Präsenz hoch über sich.",
 orte: [
  {id:"taverne", t:"Das Gasthaus Grimsted", p:55, karte:"teufel_karte_grimsted", hier:["kromutter","jensen"],
   text:["Das Gasthaus Grimsted, dessen Äußeres im Abschnitt Ankunft beschrieben ist, ist im Grunde das dänische Gegenstück zu einem Posthaus. Es ist in erster Linie ein Ort, an dem Reisende auf der Straße Essen und Unterkunft finden, dient aber auch als Wartungsstation des Postdienstes, an der Pferde gewechselt und Räder repariert werden. So ist es zugleich eine Art örtliches Postamt und eine Verbindung zur Außenwelt für die Menschen des Moors. Dazu gehören die Angestellten der Moorgesellschaft, die mehrmals die Woche zu „Kromutter“ Pedersen kommen, um Briefe und andere Lieferungen aus Viborg abzuholen. Abends dient die recht große Gaststube – die tatsächlich das gesamte Erdgeschoss einnimmt – auch als Treffpunkt, an dem die Einheimischen Kromutters berühmten Kaninchenbraten genießen. Das Essen ist einfach, aber gut zubereitet und wird mit lokal erzeugten Getränken wie Torfbier und heidekrautgewürztem Schnaps heruntergespült. Die Schlafbereiche liegen im zweiten Stock: kleine Nischen mit extrem niedrigen Decken, die kaum mehr als ein einfaches Bett und einen Nachttopf enthalten.",
          "Die Wirtin ist Kromutter Pedersen. Ihr Mann starb im Krieg mit den Preußen, in dem sie auch ihr rechtes Bein und einen Großteil des Gehörs auf dem rechten Ohr verlor. Sie ist eine rundliche Dame in spätem mittlerem Alter, die ihre Gäste liebt, besonders jene aus der Ferne. Sie erzählt den Spielercharakteren gern alles, was sie über die Gegend und ihre Menschen weiß, einschließlich Klatsch und alter Sagen. Der Spielleiter kann Kromutter nutzen, um Stücke wichtiger Informationen zu verteilen, die die Spielercharaktere an anderen Orten womöglich verpasst haben. In der Gaststube können die Spielercharaktere auch auf Leute aus Grimsted Hus treffen, darunter die berüchtigten Brüder Hans und Ejnar Jensen. Auch Kutscher Julius ist hier, und er hat Interessantes über den vielgerühmten Gabriel Sandemann zu sagen."],
   herausf:["Mit Ausnahme von Kromutter und dem Postkutscher sind die Leute im Gasthaus Grimsted zurückhaltend, wenn es darum geht, mit den Spielercharakteren zu sprechen. Sie können das Vertrauen der Einheimischen vorübergehend durch MANIPULATION oder durch Schnaps gewinnen, werden sie aber verärgern, wenn sie weiter Fragen zu „außergewöhnlichen Angelegenheiten“ wie Teufelsverehrung und den seltsamen Ereignissen um die Dampfmaschine der Moorgesellschaft stellen.",
            "Schließlich verlassen Hans und Ejnar das Gasthaus mit mürrischer Miene und gehen hinaus aufs Moor. Mit einer gelungenen Probe auf WACHSAMKEIT können die Spielercharaktere ihnen bis nach Grimsted Hus folgen, wo die Brüder ihre ältere Schwester Jensine über die schnüffelnden Fremden informieren. Das kann zu einem Hinterhalt auf dem Moor führen – Näheres siehe die Beschreibung von Grimsted Hus. Hält der Spielleiter den Zeitpunkt für gekommen, können Hans und Ejnar stattdessen übers Moor zum Lager der Moorgesellschaft eilen, wo Schritt 2 des Countdowns eintritt."],
   hinwText:"Die Spielercharaktere können im Gasthaus Grimsted viel erfahren, sowohl über die Leute von Grimsted Hus als auch über den alten Pestfriedhof.",
   hinw:[
    {id:"t1", x:"Kromutter ist eine wahre Fundgrube an Informationen und freut sich unbändig, zu teilen, was sie weiß – und was nicht. So hat sie zum Beispiel nie von jemandem namens Sandemann gehört und spottet über die Geschichten von Teufelsanbetern. Sie räumt ein, dass die Leute aus Grimsted Hus im Allgemeinen recht eigenartig sind, aber sie hat nie etwas von schwarzer Magie oder geopferten Kindern gehört – und schon gar nichts von einem Teufel im Moor."},
    {id:"t2", x:"Wenn es dunkle Mächte sind, wegen derer sie sich Sorgen machen, empfiehlt Kromutter, sich den alten Pestfriedhof auf Grimsted Lyng genauer anzusehen. Dort liegen nicht nur Pestopfer begraben, sondern auch Selbstmörder, ungetaufte Kinder, unverheiratete Mütter und andere, die als unwürdig für den regulären Friedhof an der Landstraße nach Viborg galten."},
    {id:"t3", x:"Fragen die Spielercharaktere sie nach dem seltsamen Vogel, erklärt Kromutter, dass Mylinge und andere Wiedergänger ermordeter Kinder durchaus in Vogelgestalt auf dem Moor spuken könnten. Sie fügt hinzu, dass es in der Gegend viele alte Geschichten über Mylinge gibt. Sie beschreibt sie als einsame verlorene Seelen, die nur hinübergehen wollen – und wieder mit ihren Müttern vereint sein."},
    {id:"t4", x:"Abends sitzen Hans und Ejnar Jensen immer allein in einer Ecke der Gaststube und heulen vor boshaftem Gelächter. Sie sind stets leicht betrunken und starren die Spielercharaktere skeptisch an. Die Brüder antworten ungern auf Fragen, aber wenn die Spielercharaktere eine Probe auf MANIPULATION bestehen, murmeln sie rätselhaft etwas darüber, dass Rasmussen und seine feine Maschine nicht aufs Moor gehören – und dass sie bald weg sein werden. Das passiert Außenstehenden gewöhnlich."},
    {id:"t5", x:"Der ältere Postkutscher Julius, der zwischen den Fahrten im Gasthaus ausruht, kann den Spielercharakteren viel über Sandemann erzählen, wenn sie ihm einen Schnaps spendieren. Julius’ verstorbener Vater fuhr ebenfalls eine Postkutsche und hatte die große Ehre, „den berühmten Sandemann“ auf seinen häufigen Reisen in der Gegend mehrfach zu befördern. Julius selbst lernte Sandemann nie kennen, aber sein Vater beschrieb ihn als schneidigen Mann, der die Gabe der Rede hatte und einen seltsamen Einfluss auf die Menschen um ihn – besonders auf „Weibsvolk“, sagt Julius. Sein Vater behauptete, Sandemann habe in jedem Dorf Dänemarks eine Liebste gehabt. Es müsse auch „eine kleine Armee unehelicher Kinder“ geben, kichert der alte Kutscher."}
   ]},
  {id:"lager", t:"Das Lager der Moorgesellschaft", p:58, karte:"teufel_karte_grimsted", hier:["rasmussen","arbeiter","ludvigsen"],
   text:["Preben Rasmussen und seine Mannschaft haben ihr Lager etwa zehn Kilometer westlich des Gasthauses Grimsted aufgeschlagen. Der Ort ist relativ leicht zu finden, denn der einst schmale und unscheinbare Wildpfad wurde von den Angestellten der Moorgesellschaft, die im vergangenen Jahr schwere Karren hin- und hergezogen haben, zu einer kleinen Straße ausgebaut. Das Lager liegt in einer Senke auf einem Landstreifen, der in ein Moor hineinragt. Es ist ein trostloser Ort mit hohem Schilf und schwarzen Tümpeln, in herbstlichen Dunst gehüllt.",
          "Das Lager besteht aus zehn großen Zelten aus Holz und Segeltuch sowie einem beeindruckenden Wagenpark mit Karren und Wagen verschiedenster Formen und Größen. Im Zentrum des Lagers steht eine riesige torfbefeuerte Dampfmaschine, die ständig Wasser aus dem Moor durch ein kunstvolles System gusseiserner Rohre und dicker Schläuche aus vulkanisiertem Gummi pumpt. Das Fauchen und Zischen der Dampfmaschine ist aus mehreren Kilometern Entfernung zu hören, und im Lager gehören auch das ständige Gluckern und Schlürfen der Pumpe zur Geräuschkulisse. Das Wasser wird aus dem Moor gesaugt und über ein System frisch gegrabener Kanäle und bestehender Bäche nach Grimsted geleitet. Doch das System ist noch nicht perfekt, und ein Großteil von Preben Rasmussens Arbeit dreht sich um das Auslaufproblem – was soll mit dem überschüssigen Entwässerungswasser geschehen?",
          "Außer Preben Rasmussen und dem Ersten Assistenten Jens Ludvigsen besteht das Team aus vierzehn kräftigen Arbeitern. Dazu kommen eine Köchin und zwei Küchenjungen, die das Kantinenzelt betreiben und dreimal täglich einfache, aber reichliche Mahlzeiten servieren. Die Spielercharaktere werden auf Kosten der Moorgesellschaft verpflegt und in einem eigenen Zelt untergebracht, in dem sie die Nächte des Mysteriums verbringen können. Die Zelte sind mit Öfen beheizt und mit einfachen Holzpritschen mit Schaffellen und speziell angefertigten Schlafsäcken aus gepolstertem Stoff ausgestattet. Die meisten Zelte sind außerdem mit Klapptischen und Klapphockern eingerichtet, einige auch mit Aktenschränken und anderen Büromöbeln."],
   herausf:["Die Herausforderungen im Lager haben meist mit der Spannung unter den Arbeitern zu tun, aber auch das Moor selbst ist gefährlich.",
            "Preben Rasmussen hat mehrere Tage auf das Eintreffen der Spielercharaktere gewartet. Sobald sie ankommen, führt er sie zu einem der Lagerzelte und plappert eifrig von einem „satanischen Fund“. Er ist äußerst beharrlich und mehr als nur ein wenig aufdringlich und lässt die Spielercharaktere keine eigenen Nachforschungen anstellen, bevor er ihnen seine Theorien und Beobachtungen dargelegt hat (siehe Hinweise).",
            "Es besteht stets die Gefahr, dass eine Schlägerei ausbricht, wenn die Spielercharaktere mit den Arbeitern reden. Sie sind müde und von den seltsamen Ereignissen der letzten Zeit traumatisiert. Eine gelungene Probe auf MANIPULATION oder INSPIRATION kann sie zum Reden bringen, doch wenn du die Fragen der Spielercharaktere für zu aufdringlich hältst, braucht es eine weitere Probe auf MANIPULATION, um Gewalt zu vermeiden. Die Arbeiter kämpfen mit den Fäusten, und bei einem Misserfolg fliegt ein harter rechter Haken auf eine der Spielerfiguren zu. Der Kampf zieht die übrigen Arbeiter an, und wenn die Spielercharaktere keine dritte Probe auf MANIPULATION bestehen, artet die Lage in eine Massenschlägerei aus. Sie wird W6 Runden später unterbrochen, wenn Preben Rasmussen angerannt kommt und mit der ganzen Hand herumfuchtelt."],
   hinwText:"Das Lager birgt mehrere Hinweise, sowohl auf das ermordete Kind als auch auf den Konflikt zwischen der Moorgesellschaft und den Einheimischen. Der wichtigste Hinweis ist Sandemanns Tagebuch, das wichtige Stellen und ein Foto von Signe Andersdotter enthält.",
   hinw:[
    {id:"l1", x:"Die Überreste des Namenlosen liegen auf einer groben Werkbank in einem Lagerzelt, zu dem Rasmussen die Spielercharaktere führt. Viel ist nicht übrig: ein paar Knochenfragmente und der teilweise zerdrückte Schädel eines Säuglings. Eine Spielerfigur, die eine Probe auf UNTERSUCHUNG oder HEILKUNDE besteht, erkennt, dass er einem sehr kleinen Kind gehörte, wahrscheinlich einem Neugeborenen. Die Figur begreift auch, dass das Skelett recht alt sein muss, mindestens einige Jahrzehnte."},
    {id:"l2", x:"Rasmussen ist absolut sicher, dass die Menschen des Moors einen dämonischen Wächter beschworen haben, um den menschlichen Fortschritt aufzuhalten. Die Moorgesellschaft wurde von Anfang an feindselig empfangen, und die „Tölpel“ von Grimsted Hus haben mehrere Versuche unternommen, Rasmussens Dampfmaschine zu zerstören."},
    {id:"l3", x:"Als Beweis für seine Hypothese legt er ein altes ledergebundenes Notizbuch vor – Sandemanns Tagebuch. Er zeigt den Spielercharakteren die beiden Einträge über „den Teufel im Moor“ und „die Teufelsanbeter in Grimsted Hus“ (Handouts 3E und 3F) und liest sie mit pompöser Stimme laut vor."},
    {id:"l4", x:"Das Tagebuch enthält eine Reihe wichtiger Hinweise, darunter eine unscharfe Daguerreotypie von Signe Andersdotter (Handout 3G und eigener Kasten)."},
    {id:"l5", x:"Die altmodische Handschrift zu lesen erfordert eine gelungene Probe auf WISSEN. Das Tagebuch hat keinen Titel, aber die erste Seite beginnt mit den Worten „Aufzeichnungen von Grimsted Lyng von G Sandemann“. Sein Inhalt besteht überwiegend aus langen und ziemlich langweiligen Berichten über alten „Aberglauben“ und „Teufelsverehrung“, mit Verweisen auf verschiedene unterirdische Vaesen, die nach Sandemanns Behauptung Ausgeburten der Hölle sind. Interessant am Tagebuch sind seine vielen Verweise auf die junge Bäuerin in Grimsted Hus, die offenbar Sandemanns Vertraute wurde."},
    {id:"l6", x:"Eine in Magie bewanderte Spielerfigur oder eine mit der Gabe Sechster Sinn spürt, dass mit dem Buch selbst etwas Beunruhigendes ist. Die Figur kann es nicht genau benennen, aber es scheint mit schlechten Erinnerungen verbunden zu sein."},
    {id:"l7", x:"Spielerfiguren, die sich die Dampfmaschine genauer ansehen und eine Probe auf UNTERSUCHUNG bestehen, finden Zeichen äußerer Angriffe. Mehrere Schläuche zeigen Schnittspuren eines Messers, und jemand hat offenbar versucht, die Rohre und Kolben loszuhebeln. Etwas abseits der Dampfmaschine liegt im Gras ein abgenutztes Messer mit einem eingravierten Namen: Jens Erik Jensen, G H."},
    {id:"l8", x:"Mit einer gelungenen Probe auf WACHSAMKEIT hören die Spielerfiguren ein leises Wimmern aus dem Moor. Es könnte der Ruf eines unbekannten Watvogels sein, klingt aber eher wie ein schreiendes Baby."},
    {id:"l9", x:"Die Arbeiter können ihnen erzählen, dass im Moor ein Teufelsspuk lauert. Der unverkennbare Laut eines weinenden Kindes ist von dort manchmal zu hören, gemischt mit Schreien und gottlosen Flüchen. Viele haben auch einen großen schwarzen Vogel gesehen, der das Lager zu beobachten scheint. Manche behaupten sogar, ihn lachen gehört zu haben – klang es nicht wie ein glucksendes Baby?"},
    {id:"l10", x:"Die Köchin und ihre Küchenjungen erzählen gern von ihren Erfahrungen. Wie die Arbeiter sind sie überzeugt, dass etwas „nicht stimmt“, vermuten aber, dass die Einheimischen dahinterstecken."},
    {id:"l11", x:"Die Küchenjungen besuchen oft das Gasthaus Grimsted, um Post und Lebensmittel abzuholen, und haben mit eigenen Ohren Raufbolde in der Gegend damit prahlen hören, die Moorgesellschaft zu sabotieren. Zwei junge Männer aus Grimsted Hus kommen ihnen besonders bedrohlich vor: Hans und Ejnar, die oft über „die Teufelsmaschine aus Kopenhagen“ wettern."},
    {id:"l12", x:"Einer der Küchenjungen, der junge Severin, kann ihnen von einem unheimlichen alten Friedhof etwa fünf Kilometer westlich von hier erzählen. Er ist bei Versorgungsgängen durch die Gegend gekommen und beschreibt den Friedhof als gespenstischen Ort mit bemoosten Grabsteinen – viele davon namenlos, aber alle uralt und stark verwittert."},
    {id:"l13", x:"Der junge Severin erinnert sich auch, auf dem Friedhof eine alte Frau gesehen zu haben (Oma Thea). Tatsächlich hat er sie mehrmals gesehen und ist sicher, dass er sie weinen hörte."}
   ],
   kasten:[
    {t:"Ein trügerisches Moor", p:58, x:"Das Moor ist ein tückischer Ort, und Spielerfiguren, die sich in den Nebel hinauswagen, könnten einen falschen Schritt tun und unter Wasser enden. Eine gelungene Probe auf BEWEGLICHKEIT ist nötig, wenn die Spielerfiguren vom Pfad abkommen und ins Moor gehen. Bei einem Misserfolg fallen sie in einen Tümpel und müssen eine weitere Probe auf BEWEGLICHKEIT bestehen, um wieder herauszukommen (langsame Aktion). Andere Spielerfiguren können ihnen mit einer gelungenen Probe auf KRAFT helfen. Nach drei Runden im Wasser sinken die Figuren unter die Oberfläche und müssen jede Runde eine Probe auf KRAFT bestehen, um die Luft anzuhalten. Ein Misserfolg bedeutet, dass die Figuren zu ertrinken beginnen und für jede Runde unter Wasser einen körperlichen Zustand erleiden."},
    {t:"Sandemanns Tagebuch", p:59, x:"Es ist wichtig für das Mysterium, dass die Spielercharaktere das Tagebuch nicht nur näher betrachten, sondern zum Pestfriedhof bringen. Begreifen die Spielercharaktere das nicht, kann Rasmussen darauf bestehen, dass sie es bei ihren Nachforschungen als eine Art „okkulten Atlas“ von Grimsted Lyng mitnehmen."},
    {t:"Eine vergilbte Fotografie", p:60, x:"Als die Spielercharaktere Sandemanns Tagebuch durchblättern, rutscht eine vergilbte Daguerreotypie heraus. Es ist ein körniges Porträt einer jungen Bäuerin mit runden Wangen und dicken Zöpfen. Ihre ernsten Augen blicken fast anklagend in die Kamera. Das Foto scheint zwischen die Seiten des Tagebuchs gesteckt worden zu sein, doch wenn die Spielercharaktere Rasmussen danach fragen, wirkt er ziemlich uninteressiert. „Wahrscheinlich nur irgendein dummes Mädchen von hier“, sagt er und fügt hinzu, sie sollten sich lieber auf den satanischen Kult konzentrieren."}
   ]},
  {id:"hus", t:"Grimsted Hus", p:62, karte:"teufel_karte_grimsted", hier:["jensine","jensen","thea"],
   text:["Grimsted Hus ist eine kleine Siedlung aus etwa einem Dutzend Steinhäusern mit Heidedächern, die sich um einen alten Schäferpfad drängen. Die meisten sind Wohnhäuser, dazwischen liegen verschiedene Arten von Nebengebäuden, Schuppen und eingezäunte Ställe.",
          "Die Menschen in Grimsted Hus sind meist Schäfer und Torfstecher – strenge, ernste Typen, die ein hartes und einfaches Leben führen, in dem das windumtoste Moor sowohl ihr Lebensunterhalt als auch ihr Fluch ist. Schafe und die gelegentliche magere Kuh streifen frei zwischen den Gebäuden umher. Ältere Leute sitzen an den Hauswänden, schnitzen Holz oder flechten Körbe aus Heidekraut. Ein paar erwachsene Männer schärfen neben einem Schuppen ihre Sensen, und eine stämmige Bäuerin mit kräftigen Unterarmen schaufelt vor einem der Ställe Mist. Eine Schar schmutziger Kinder rennt auf die Spielercharaktere zu, als sie sich der Siedlung nähern.",
          "Mit Ausnahme von Oma Thea weiß jeder Erwachsene in Grimsted Hus, dass die Jensen-Brüder wiederholt versucht haben, die Dampfmaschine der Moorgesellschaft zu zerstören. Aber niemand will es den Spielercharakteren sagen. Hans und Ejnar gelten allgemein als betrunkene Halunken, doch die Nachbarn dulden sie aus Respekt vor ihren verstorbenen Eltern und ihrer starken und weithin gefürchteten älteren Schwester Jensine."],
   herausf:["Die Menschen in Grimsted Hus sind Fremden gegenüber misstrauisch, aber die Einzigen, die gefährlich und gewaltbereit sein könnten, sind die Jensen-Geschwister.",
            "Stellen die Spielercharaktere aufdringliche Fragen oder verraten, dass sie das verlorene Messer gefunden haben, holen Hans und Ejnar Jensine und bereiten irgendwo auf dem Moor einen Hinterhalt vor, um ihnen „etwas Verstand einzubläuen“. Spielerfiguren, die eine Probe auf WACHSAMKEIT gegen die HEIMLICHKEIT der Geschwister bestehen, bemerken drei schattenhafte Gestalten, die sich weiter unten am Pfad hinter einem Felsen verstecken. Die Geschwister wollen die Spielercharaktere nicht töten – ihr Plan ist nur, die sich einmischenden Fremden zu erschrecken und zu demütigen. Der Angriff beginnt damit, dass Hans und Ejnar mit ihren Fernwaffen über die Köpfe der Spielercharaktere schießen, worauf Jensine ihnen den Kopf eines frisch geschlachteten Schafes entgegenwirft. Sie kommt den Pfad herabgestürmt und schwingt ihre riesige Axt in der Luft, während ihre Brüder die Spielercharaktere warnen, sie sollten „sofort nach Hause gehen“, sonst werde es böse für sie enden. Die Geschwister verteidigen sich, wenn die Spielercharaktere zurückschlagen, wenden sonst aber keine weitere Gewalt an.",
            "Stellen die Spielercharaktere Fragen über Sandemann oder die örtliche Geschichte, werden sie an Oma Thea verwiesen – die Einzige, die alt genug ist, sich an die alten Zeiten zu erinnern. Thea wohnt in einer windschiefen alten Kate etwas abseits der anderen Gebäude. Sie ist weit entgegenkommender als die anderen und bietet den Spielercharakteren köstlichen Löwenzahnwein an. Leider ist ihr Geist offenkundig altersverwirrt, und sie fragt, ob die Spielercharaktere gekommen sind, um sich dem Kriegseinsatz gegen die Preußen anzuschließen."],
   hinwText:"",
   hinw:[
    {id:"h1", x:"Das abgenutzte Messer, das im Lager der Moorgesellschaft gefunden werden kann, ist ein Erbstück der Jensens. Jeder in Grimsted Hus erkennt das Messer und weiß, dass sich der eingeschnitzte Name auf ihren verstorbenen Vater Jens Erik bezieht. Niemand will die Wahrheit sagen, wenn die Spielercharaktere ihnen das Messer zeigen, aber sein Anblick weckt mächtige Gefühle in ihnen. Mit einer gelungenen Probe auf BEOBACHTUNG erkennen die Spielercharaktere, dass die betreffende Person wegen des Messers lügt. Zeigen sie es den Jensens, folgen diese den Spielercharakteren aufs Moor, wie unter Herausforderungen beschrieben."},
    {id:"h2", x:"Spielerfiguren, die die Gegend absuchen und eine Probe auf UNTERSUCHUNG bestehen, finden etwas, das wie eine Reihe kleiner heidnischer Götzenbilder aussieht, zusammengebunden mit Heidekraut und verschiedenen Kräutern. Mehrere davon finden sich in den Ställen und in einigen der Wohnhäuser. Eine gelungene Probe auf WISSEN zeigt, dass es sich um bäuerliche Talismane gegen das Böse handelt."},
    {id:"h3", x:"Vor Oma Theas Kate wachsen wild Herbstpfingstrosen und Vergissmeinnicht. Spielerfiguren, die den Pestfriedhof besucht haben, erinnern sich, dass die Sträuße, die auf dem gut besuchten Grab – der letzten Ruhestätte von Signe Andersdotter – liegen, aus genau diesen Blumen bestanden."},
    {id:"h4", x:"Oma Thea wirkt fröhlich und verwirrt, aber jede Erwähnung von Sandemann bringt sie plötzlich zum Weinen. Gehen die Spielercharaktere anständig damit um – etwa indem sie versuchen, sie zu trösten –, beginnt sie, von ihrer Tochter Signe zu erzählen, die sich in den gutaussehenden Sandemann verliebte. Sie erzählt von der Schwangerschaft, von Sandemanns Verrat und davon, wie Signe erfroren auf dem Moor gefunden wurde. Aber das Kind wurde nie gefunden, schließt sie: „Ich glaube, es ist noch da draußen – und sucht nach meiner kleinen Signe.“"},
    {id:"h5", x:"Zeigen die Spielercharaktere ihr Sandemanns Tagebuch, wird Oma Thea aufgebracht und murmelt etwas von einem schwarzen Herzen und „den Erinnerungen eines bösen Mannes“. Sie bittet sie, das Tagebuch loszuwerden, am besten indem sie es vernichten – das könnte ihrem Enkelkind Frieden bringen."}
   ]},
  {id:"friedhof", t:"Der Pestfriedhof", p:65, karte:"teufel_karte_grimsted", hier:["thea"],
   text:["Etwa fünf Kilometer westlich vom Lager der Moorgesellschaft liegt der uralte und bemerkenswerte Friedhof, den die Einheimischen „den Pestfriedhof“ nennen. Er ist von einer bemoosten Steinmauer umgeben und beherbergt etwa hundert Grabsteine sowie gelegentlich ein Holzkreuz, eingehüllt in kühlen Herbstnebel. Fast alle Gräber sind unbeschriftet. Eine Ausnahme ist ein düsterer Standstein mit einer schlichten Inschrift: „Hier ruhen unsere Toten von der schrecklichen Pestilenz, die im Jahr des Herrn 1710 während des Großen Krieges mit Schweden das Land heimsuchte.“",
          "Viele der Grabsteine bröckeln vor Alter. Der Friedhof wirkt nicht nur öde und verlassen, sondern auch verstoßen – und absichtlich vergessen. Es ist ein Ort, an dem die Unreinen und Unerwünschten zur Ruhe gebettet wurden. Neben Pestopfern sind hier Selbstmörder, hingerichtete Diebe, uneheliche Kinder und mehrere unverheiratete Mütter begraben. Eine von ihnen ist die Mutter des Namenlosen, Signe Andersdotter, deren Überreste unter einem unbeschrifteten Grabstein im Schatten der Mauer auf der Westseite des Friedhofs ruhen."],
   herausf:["Die Spielerfigur, die Sandemanns Tagebuch trägt, wird in dem Moment, in dem sie die Friedhofsmauer betritt, von äußerst lebhaften und unangenehmen Visionen heimgesucht. Vier verstörende Szenen ziehen in einer Kavalkade des Grauens vorbei:",
            "· Ein riesiger Mann mit breitkrempigem Priesterhut stößt eine jüngere Bäuerin mit den Worten weg: „Es ist nicht mein Kind, unreines Weib!“ Es ist die rundwangige Frau vom Foto in Sandemanns Tagebuch – keine Probe ist nötig, um sie zu erkennen.",
            "· In der nächsten Vision küsst dieselbe Bäuerin ein neugeborenes Kind auf die Stirn. Das Baby gluckst liebevoll, doch die Frau weint.",
            "· Dann geht die Vision in ein unwirtliches Sumpfgebiet mit wucherndem Schilf und wirbelnden Nebelschwaden über – einen Ort, den die Spielerfigur als das Moor am Lager der Moorgesellschaft erkennt.",
            "· Das Letzte, was die Figur sieht, ist, wie das weinende Kind langsam in das schwarze Moor hinabgelassen wird, wo es nach einem kurzen Gurgeln plötzlich verstummt. Die Spielerfigur muss eine Furchtprobe gegen Furcht 2 ablegen."],
   hinwText:"",
   hinw:[
    {id:"f1", x:"Eine Spielerfigur, die eine Probe auf UNTERSUCHUNG besteht, bemerkt, dass eines der Gräber breiter ist und häufiger besucht wird als die anderen. Das ist natürlich das Grab von Signe Andersdotter, das Oma Thea mindestens einmal die Woche besucht. Um das Grab gibt es Fußspuren, und die Erde vor dem Stein ist gesund und gut geharkt. Und anders als bei allen anderen Gräbern auf dem Pestfriedhof liegen rund um Signe Andersdotters Grabstein mehrere halb verwelkte Sträuße."},
    {id:"f2", x:"Spielerfiguren, die sich die Sträuße genauer ansehen, erkennen, dass sie aus Herbstpfingstrosen und Vergissmeinnicht bestehen – denselben Blumen, die vor Oma Theas Kate wachsen."},
    {id:"f3", x:"Spielerfiguren, die eine Probe auf WACHSAMKEIT bestehen, bemerken, dass der schwarze Vogel auf einem der Grabsteine sitzt und sie beobachtet."}
   ]}
 ],

 kf: {
  p: 65,
  einleitung:["Die Konfrontation findet höchstwahrscheinlich auf dem Pestfriedhof statt. Die Spielercharaktere können aus verschiedenen Gründen dort landen. Haben sie alle anderen Hinweise verpasst, könnten sie Oma Thea auf einem ihrer Gänge von Grimsted Hus zum Grabstein ihrer Tochter folgen.",
                "Besuchen die Spielercharaktere das Grab vor Schritt 3 des Countdowns, geschieht nichts weiter als das, was in der Ortsbeschreibung des Pestfriedhofs steht. Kommen sie jedoch nach Schritt 3, können die Spielercharaktere den Namenlosen dazu bringen, sich zu zeigen. Das kann geschehen, indem sie nach dem Myling rufen – etwa „Komm heraus, kleines Kind!“ – oder einfach ein paar entschlossene Schritte auf den Vogel zugehen, der ihnen folgt. Sind die Spielercharaktere passiv und unentschlossen, kannst du Rasmussen (oder möglicherweise Oma Thea) einsetzen, um eine Reaktion des Mylings zu erzwingen. Rasmussen könnte die Spielercharaktere zum Beispiel auf dem Pestfriedhof einholen und sie warnen, dass der Ort von dämonischen Mächten heimgesucht wird, und dabei aufgeregt auf Sandemanns Tagebuch verweisen. Haben sie das Tagebuch noch nicht in die Hände bekommen, kannst du Rasmussen es einer der Spielerfiguren praktisch in die Hand drücken lassen, die sofort von den unter Herausforderungen des Pestfriedhofs beschriebenen Visionen getroffen wird."],
  wege: [
   {t:"Der Namenlose erscheint", x:[
    "Der Namenlose erscheint den Spielercharakteren in Geistergestalt, wenn Schritt 3 des Countdowns eingetreten ist. Solange Sandemanns Tagebuch existiert, handelt der Myling als mörderischer Rächer und greift Rasmussen oder die Spielerfigur, die das Tagebuch trägt, mit voller Raserei an – vor allem mit dem Fluch TODESKÄLTE (ausgespiene Schwälle eiskalten Moorwassers)."]},
   {t:"Das Tagebuch vernichten", x:[
    "Die Angriffe hören auf, sobald das Tagebuch vernichtet ist, am besten durch Feuer, obwohl jede Methode, die zur völligen Zerstörung führt, dieselbe Wirkung hat. Mit anderen Worten: Es reicht nicht, es auf dem Moor wegzuwerfen oder in der Erde zu vergraben. Ist das zu schwer herauszufinden, kannst du eine der Spielerfiguren sich an Oma Theas Worte erinnern lassen, dass das Tagebuch vernichtet werden muss, um ihrem Enkelkind Frieden zu bringen. Thea könnte sogar zwischen den Grabsteinen auftauchen und sie anschreien, sie sollten das Tagebuch „um Himmels willen“ vernichten."]},
   {t:"Den Myling bannen", x:[
    "Um den Myling zu bannen, müssen die Spielercharaktere seine Überreste im Grab von Signe Andersdotter auf dem Pestfriedhof beisetzen. Das Wichtigste für den Namenlosen ist, wieder mit seiner Mutter vereint zu sein. Ihn zu benennen ist ebenfalls willkommen, aber in diesem speziellen Fall nicht entscheidend. Spielerfiguren, die vor Signe Andersdotters Grabstein graben, finden ihr Skelett etwa eineinhalb Meter unter der Erde.",
    "Sobald das Skelett freigelegt ist, verdunkelt sich der Himmel durch schwarze Wolken, und ein heulender Herbstwind fegt über den Friedhof. Der Myling taucht aus den Schatten auf und späht sehnsüchtig in das Grab, Tränen in seinen schimmernden grünen Augen.",
    "Damit das Ritual gelingt, müssen die Spielercharaktere die Überreste des Namenlosen neben seine Mutter legen, am besten in körperlichem Kontakt mit ihrem Skelett. Der Geist von Signe Andersdotter erscheint dann in Gestalt einer flackernden, vage menschenähnlichen Erscheinung, die leuchtend wie eine Lichtsäule aus dem Grab aufsteigt. „Mein Kind“, sagt sie und umarmt den Namenlosen, der im Licht verschwindet. Alles wird dunkel und still. Die Herbststürme haben aufgehört zu heulen, und alles ist friedlich. Das Ritual wird abgeschlossen, indem das Grab wieder mit Erde gefüllt und der Grabstein an seinen Platz zurückgestellt wird."]}
  ]
 },

 ns: {p: 67, t: "Nachspiel", x:["Werden die Überreste des Mylings mit seiner Mutter beigesetzt, findet der Namenlose Frieden und verschwindet aus Grimsted Lyng. Rasmussen ist zutiefst dankbar und erklärt, dass die Spielercharaktere jederzeit auf ihn und „die mächtige Moorgesellschaft“ zählen können, falls sie in Zukunft Hilfe brauchen.",
   "Haben die Spielercharaktere das Mysterium jedoch nicht gelöst, spukt der Namenlose weiter auf dem Moor und verursacht unsägliche Probleme für alle, die in der Gegend leben und arbeiten."]},

 figOrder: ["rasmussen", "ludvigsen", "kromutter", "jensen", "jensine", "thea", "arbeiter"],
 figs: {
  rasmussen: {n:"Preben Rasmussen", rolle:"Chefingenieur der Moorgesellschaft", zitat:"„Gegen den menschlichen Fortschritt lässt sich nichts einwenden.“", p:61, img:"som/teufel_preben_rasmussen",
   x:"Preben Rasmussen ist ein herrischer Mann in den Vierzigern. Als Dampfingenieur an der Polytechnischen Universität Dänemarks ausgebildet, arbeitet er seit zehn Jahren für die Moorgesellschaft. Der Posten auf Grimsted Lyng ist sein erster Auftrag als Chefingenieur, und er nimmt ihn äußerst ernst. Für Rasmussen ist er viel mehr als eine Arbeit. Die Modernisierung des Moors ist ein zivilisatorischer Kreuzzug gegen die Mächte der Finsternis und Barbarei.<br><br>Rasmussen besitzt nicht das Zweite Gesicht, ist aber durch das Studium alter Texte überzeugt, dass nichtmenschliche Vaesen mit übernatürlichen Kräften eine empirische Realität sind. Während seines Studiums in Kopenhagen hatte Rasmussen Kontakt zu mehreren Rosenbergern und ließ sich von ihrer negativen Sicht auf das Nichtmenschliche beeinflussen. Er sieht Vaesen als unglückliche Überreste aus dem Zeitalter der Dunkelheit und Barbarei – das Gegenteil von allem, wofür die Moorgesellschaft und der Ingenieursberuf stehen. Daher ist klar, dass das Nichtmenschliche ausgerottet werden muss, um Platz für den menschlichen Fortschritt zu schaffen.",
   a:[3,3,4,1], f:[["Beweglichkeit",2],["Kraft",2],["Heimlichkeit",2],["Fernkampf",3],["Wissen",4],["Wachsamkeit",3],["Inspiration",4],["Beobachtung",3]], z:[2,2], ausr:"Pistole, Sandemanns Tagebuch", hier:"Lager der Moorgesellschaft"},
  ludvigsen: {n:"Jens Ludvigsen", rolle:"Erster Assistent und wissenschaftlicher Sekretär", zitat:"„Der Chefingenieur wäre damit nicht zufrieden.“", p:53, img:"som/teufel_jens_ludvigsen",
   x:"Jens Ludvigsen ist ein frisch diplomierter Ingenieur der Polytechnischen Universität Dänemarks. Er ist auf künstlichen Dünger spezialisiert, und der langfristige Plan sieht vor, dass Ludvigsen die Verantwortung für die Modernisierung des Moors übernimmt, wenn Rasmussen das Entwässerungsprojekt abschließt.<br><br>Ludvigsen ist ein elegant gekleideter und gepflegter Mann Mitte zwanzig. Er hat tiefen Respekt vor Rasmussens Autorität, tut sich aber schwer, seine Tiraden über „Finsternis und Barbarei“ und die ständigen Verweise auf Sandemanns Tagebuch zu verstehen. Ludvigsen ist im Herzen ein praktischer Mann, der der empirischen Wissenschaft ergeben ist und voller Träume steckt, die Erde mit dem allerneuesten künstlichen Dünger anzureichern.",
   a:[2,2,4,3], f:[["Beweglichkeit",2],["Kraft",2],["Wissen",3],["Wachsamkeit",3],["Inspiration",2],["Beobachtung",3],["Untersuchung",3]], z:[2,1], ausr:"Dicker Spazierstock, Glas mit Proben künstlichen Düngers", hier:"Gasthaus · Lager"},
  kromutter: {n:"Kromutter Pedersen", rolle:"Wirtin des Gasthauses Grimsted", zitat:"„Die Unterirdischen gehören ganz natürlich zur Geschichte des Moors. Das kann man von den Preußen nicht sagen.“", p:57, img:"som/teufel_kromutter",
   x:"Kromutter Pedersen ist eine imposante Soldatenwitwe in den Fünfzigern. Sie wuchtet ihren kräftigen Körper auf einem alten Holzbein umher, das ständig auf den knarrenden Dielen des Gasthauses klopft. Die Geschichte war hart zu Kromutter und ihrer Familie, die sie im letzten Krieg mit den Preußen verlor. Heute ist es das Gasthaus Grimsted, das ihrem Leben Sinn gibt. Sie ist überaus gesellig und teilt gern alle Geschichten, Sagen und Gerüchte über Grimsted Lyng und seine Menschen, auf die sie im Lauf der Jahre gestoßen ist. Das Einzige, was Kromutter nicht ausstehen kann, sind Preußen und die deutsche Kultur im Allgemeinen. Spricht eine Spielerfigur mit deutschem Akzent oder hat einen deutsch klingenden Namen, ist Kromutter dieser Person gegenüber sehr zurückhaltend.",
   a:[4,2,3,4], f:[["Beweglichkeit",2],["Kraft",2],["Wachsamkeit",4],["Beobachtung",3],["Untersuchung",3]], z:[2,2], ausr:"Kaminschürhaken, Tonpfeife, Tabaksbeutel", hier:"Gasthaus Grimsted"},
  jensen: {n:"Hans und Ejnar Jensen", rolle:"Brüder · betrunkene Saboteure", zitat:"„Zur Hölle mit den Kopenhagenern und ihren Maschinen!“ – „Ja, zur Hölle mit allen Fremden!“", p:63, img:"som/teufel_jensen_brueder",
   x:"Hans und Ejnar sind zwei betrunkene, gewalttätige junge Männer aus der Siedlung Grimsted Hus. Sie wuchsen in einem Heim ohne Eltern auf, da Mutter und Vater beide während des Krieges mit den Preußen verschwanden. Stattdessen kümmerte sich ihre ältere Schwester – die körperlich starke, aber geistig langsame Jensine – nach besten Kräften um die Familie.<br><br>Das Leben war hart zu den Brüdern und hat sie eifersüchtig auf andere Menschen gemacht, die sie als Rivalen im täglichen Überlebenskampf betrachten. Gleichzeitig sind sie außergewöhnlich arbeitsscheu und verbringen die meiste Zeit im Gasthaus Grimsted, wo sie ihr letztes Erbe vertrinken. Der Kampf gegen die Moorgesellschaft hat ihrem Leben einen höheren Sinn gegeben: das Moor und die alten Sitten gegen Angriffe von außen zu verteidigen.<br><br>Beide Brüder sind ungewaschene Männer mit schmutziger Kleidung und nicht vorhandener Zahnhygiene. Sie sind grob und ungebildet, aber verschlagen und feige. Sie scheuen keinen Streit, doch wenn es ernst wird, holen sie lieber Jensine, die ihnen stets den Rücken freihält.",
   a:[4,3,3,1], f:[["Beweglichkeit",2],["Nahkampf",3],["Kraft",3],["Heimlichkeit",4],["Fernkampf",4],["Wachsamkeit",3]], z:[2,3], ausr:"Muskete (Hans), Armbrust (Ejnar)", hier:"Gasthaus · Grimsted Hus"},
  jensine: {n:"Jensine Jensen", rolle:"Ältere Schwester von Hans und Ejnar", zitat:"„Jeder Mistkerl, der sich mit den Kleinen anlegt, kriegt die Axt zu fressen!“", p:64, img:"som/teufel_jensine",
   x:"Jensine ist eine große und ungewöhnlich muskulöse Bäuerin in den Dreißigern. Sie ist stark wie ein Ochse und so pflichtbewusst, wie man nur sein kann, hat aber einen schwachen Verstand und ein hitziges Temperament. Letzteres wird von ihren jüngeren Brüdern Hans und Ejnar oft ausgenutzt, die Jensine als Muskelkraft einsetzen, wenn sie in Streit geraten.<br><br>Jensine verehrte ihren Vater Jens Erik, der sie als seine auserwählte Erbin behandelte. Sie hält es für ihre bittere Pflicht, das, was von der zerbrochenen Familie übrig ist, gegen alles Böse zu verteidigen. Sie wird deshalb alles tun, um ihre Brüder zu beschützen, trotz der schmerzlichen Einsicht, dass keiner von ihnen den Erwartungen des verstorbenen Jens Erik gerecht wird.",
   a:[5,2,1,3], f:[["Beweglichkeit",2],["Nahkampf",5],["Kraft",5],["Heimlichkeit",2],["Wachsamkeit",2]], z:[2,4], ausr:"Riesige Holzfälleraxt (technisch als Hellebarde behandelt)", hier:"Grimsted Hus"},
  thea: {n:"Oma Thea", rolle:"Mutter von Signe Andersdotter", zitat:"„Merkt euch meine Worte, der einzige Teufel auf dem Moor war Sandemann selbst!“", p:64, img:"som/teufel_oma_thea",
   x:"Oma Thea ist eine liebe, aber verwirrte alte Bäuerin in den Achtzigern. Sie wird von ständiger Trauer über den Tod ihrer Tochter Signe Andersdotter geplagt. Signe war ihr einziges Kind und der eigentliche Sinn ihres Daseins. Thea besucht das Grab ihrer Tochter, so oft sie kann, und unterhält sie mit Liedern und kleinen Geschichten aus alter Zeit.",
   a:[2,2,4,4], f:[["Beweglichkeit",1],["Heilkunde",5],["Wissen",2],["Wachsamkeit",3],["Inspiration",3]], z:[2,2], ausr:"Ranzen mit Heilkräutern, Pfeife und Tabak, Flasche Löwenzahnwein", hier:"Grimsted Hus · Pestfriedhof"},
  arbeiter: {n:"Arbeiter der Moorgesellschaft", rolle:"Gruppe · Saisonarbeiter", zitat:"„Ehrliche Arbeit für ehrlichen Lohn – aber Gott weiß, ob es das wert ist.“", p:61, img:"",
   x:"Die meisten von Rasmussens Arbeitern sind Saisonarbeiter von nah und fern, darunter eine Handvoll Schweden, die vor der Not in ihrer verarmten Heimat geflohen sind. Es sind kräftige, bärtige Männer zwischen 20 und 40, meist verbittert und wortkarg – und zutiefst erschüttert von den seltsamen Dingen, die in der Gegend geschehen. Wenn sie nicht arbeiten, verbringen sie ihre Abende in den Zelten, schreiben Briefe an ihre Familien daheim, spielen Karten, machen Musik oder erzählen Geschichten aus der weiten Welt. Da im Lager nicht getrunken werden darf, schleichen sich einige der Arbeiter regelmäßig zum Gasthaus Grimsted, um einen Schluck oder zwei zu trinken.",
   a:[3,2,2,2], f:[["Nahkampf",3],["Kraft",3]], z:[1,2], ausr:"Hammer und Messer", hier:"Lager der Moorgesellschaft"}
 },

 nock: {n:"Der Namenlose (Myling)", p:48, x:"<img src=\"img/som/teufel_friedhof.webp\" alt=\"\" style=\"float:right;width:120px;margin:0 0 8px 12px;mix-blend-mode:multiply\">Der Namenlose ist ein Myling – Werte im Grundregelwerk S. 142–143 (<a class=\"lnk\" onclick=\"go('vaesen/myling')\">Myling</a>). Er erscheint bis zur abschließenden Konfrontation nur in Gestalt eines Vogels: ein riesiger Reiher mit schwarzen Federn und Augen, die in unheiligem grünem Licht schimmern. In Geistergestalt zeigt er sich als neugeborenes Kind, wenn auch aufgedunsen und übergroß, mit kreideweißer Haut, auf der seine geschwärzten Adern wie ein Spinnennetz aussehen. In den Tiefen seiner leeren Augenhöhlen glimmt ein grünes Licht. Das grauenhafte Geschöpf trieft vor Nässe und greift an, indem es einen Strahl eiskalten Moorwassers ausspeit, der technisch als der Fluch TODESKÄLTE wirkt (siehe Grundregelwerk S. 119). Zauber im Mysterium: Verzauberungen NEBEL, MAREEL und ÜBERHITZUNG. Furchtprobe gegen Furcht 1 bei seinen Erscheinungen im Lager."},

 ho: [
  {id:"3a", t:"Handout 3A", u:"Linneas Brief", paper:"ho_3a", form:"brief", klein:1},
  {id:"3b", t:"Handout 3B", u:"Preben Rasmussens Telegramm", paper:"ho_3b", form:"brief", klein:1, x:"<i>Vom Postamt Viborg an die Telegraphenstation Upsala</i><br><br>Verehrte Gnädige<br><br>Benötige dringend Hilfe STOPP Eindeutige dämonische Präsenz auf Grimsted Lyng STOPP Angriffe auf das Arbeitslager der Moorgesellschaft STOPP Unnatürliche Schäden an der Ausrüstung STOPP Die Männer vor Angst außer sich STOPP Zorn und Narrheit der Einheimischen STOPP Fürchte, es ist G Sandemanns Teufel STOPP Erwarte Ihre Ankunft im Gasthaus Grimsted STOPP"},
  {id:"3c", t:"Handout 3C", u:"Zeitungsartikel über die Moorgesellschaft", paper:"ho_3c", form:"brief", klein:1, x:"<b>FORTSCHRITT KOMMT INS FINSTERSTE JÜTLAND</b><br><br>Mit den allerneuesten Mitteln von Technik und Wissenschaft haben fleißige Ingenieure aus der königlichen Hauptstadt Kopenhagen es auf sich genommen, die kargen Moore der jütländischen Halbinsel zu zivilisieren. Es ist die Dänische Gesellschaft zur Urbarmachung der Heide, die vielen unserer Leser bereits bekannt sein dürfte, die diese mannhafte Initiative startet. Die Moore sollen trockengelegt, die Heide ausgejätet und germanische Bäume mit männlichen Wurzeln gepflanzt werden, um den Boden zu festigen und die Ernten vor dem Flugsand zu schützen. Ferner sollen die neuesten Wunder des künstlichen Düngers eingesetzt werden, entwickelt von den fleißigen und genialen Forschungsingenieuren der Polytechnischen Universität Dänemarks. Einer dieser furchtlosen Fackelträger der Zivilisation ist der berühmte Dampfingenieur Preben Rasmussen, der die Expedition der Moorgesellschaft in das weite Moor von Grimsted Lyng leiten wird: ein primitiver und gottverlassener Teil Dänemarks, der nach Rasmussens Worten ebenso gut im finstersten Afrika liegen könnte. „Ich habe demütig die edle Aufgabe angenommen, Zivilisation und menschlichen Fortschritt zu sichern“, sagte Herr Rasmussen unserem Reporter. Er fügt hinzu, dass seine einzige Sorge sei, wie die einheimische Bevölkerung auf seine Dampfmaschine reagieren werde: „Man hört von den Ludditen-Irren in England.“"},
  {id:"3d", t:"Handout 3D", u:"Fragment aus „Unterirdische Vaesen und ihre Verehrer im Norden“", paper:"ho_3d", form:"brief", klein:1, x:"Obwohl Studien der chthonischen Kräfte stets schwierig durchzuführen und gefährlich für Leib und Leben sind, enthält die Geschichte der nordischen Wissenschaft zahlreiche Beispiele, die selbst internationalen Leuchten wie den furchtlosen Brüdern Wilhelm und Jacob Grimm in Deutschland und dem Großmeister-Alchemisten Isaac Newton Konkurrenz machen. Ein wichtiger Pionier in unserer eigenen Ecke der Welt ist der Däne Gabriel Sandemann, der in den Jahrzehnten zwischen Bonapartes Kriegen und dem Aufkommen der Eisenbahn unter Bauern und einfachen Leuten umherreiste, um ihre Beziehung zum Unterirdischen zu dokumentieren. Sandemann war ein imposanter Mann – groß und stark an Leib und Seele –, der auf seinen vielen Reisen durch die dänische Bauerngesellschaft in ihrer letzten Blüte Tausende von Sagen und Augenzeugenberichten über unterirdische Vaesen und ihr Verhältnis zur Menschheit sammelte. Am bemerkenswertesten ist vielleicht seine Dokumentation der wundersamen und doch furchterregenden Vaesen, die die berühmten dänischen Moore heimsuchen."},
  {id:"3e", t:"Handout 3E", u:"Sandemanns Tagebuch: Der Teufel im Moor", paper:"ho_3e", form:"tagebuch", klein:1, x:"Ich werde dieses geflügelte Vaesen „den Teufel im Moor“ nennen, denn an seinem höllischen Ursprung besteht nicht der geringste Zweifel. Es wird von den Moorleuten als Schutzengel verehrt, und das seit unvordenklichen Zeiten. Diese armen verblendeten Menschen – es ist kaum übertrieben, sie Narren oder die Wilden von Danevang zu nennen – zahlen einen schrecklichen Preis für diesen dämonischen Schutz. Blut und Seelen sind es, von denen ich spreche. Blut und Seelen. Sie haben den Mächten des Moors seit je Kinder geopfert und damit ihre unsterblichen Seelen für immer dem Dunklen und dem Reich ewiger Qual gebrandmarkt."},
  {id:"3f", t:"Handout 3F", u:"Sandemanns Tagebuch: Teufelsanbetung in Grimsted Hus", paper:"ho_3f", form:"tagebuch", klein:1, x:"Grimsted Hus ist ein wilder Ort der Narrheit und gottlosen Barbarei, doch selbst hier hat unser Herr einen einzelnen Samen christlichen Anstands gepflanzt. Sie ist ein Mädchen bäuerlicher Herkunft namens Signe Andersdotter, hat aber ihren Kopf auf dem rechten Fleck und scheint sogar des Lesens kundig zu sein. Durch dieses reine, unschuldige Geschöpf habe ich Zugang zu den innersten Geheimnissen der Moorbauern gewonnen, und manchmal habe ich das Gefühl, dass die Wahrheit – der Blick auf die Wirklichkeit, den mein Feldzug der Aufklärung enthüllt hat – zu schwer für einen einzelnen Mann ist. Aber es besteht kein Zweifel mehr in dieser Sache: Hier wird seit Jahrtausenden Teufelsanbetung betrieben, und das schlagende Herz dieses uralten Kults ist Grimsted Hus."},
  {id:"3g", t:"Handout 3G", u:"Daguerreotypie von Signe Andersdotter", paper:"ho_3g", form:"bild"}
 ]
};
